			fmt.Printf("Failed to set key/value: %v\n", err)
			batch.Close()
			coll.Close()
			store.Close()
			return
		}

		err = coll.ExecuteBatch(batch, moss.WriteOptions{})
		if err != nil {
			fmt.Printf("Failed to execute batch: %v\n", err)
			batch.Close()
			coll.Close()
			store.Close()
